-- AlterTable
ALTER TABLE "perguntas" ADD COLUMN     "mensagem_nao" TEXT,
ADD COLUMN     "mensagem_sim" TEXT;


-- Mensagens padrão nos critérios que já existem (só onde ainda estão vazias).
UPDATE "perguntas" SET "mensagem_sim" = 'Você recebeu o cliente com um cumprimento — bom dia, boa tarde ou boa noite. A primeira impressão começou do jeito certo.', "mensagem_nao" = 'O atendimento começou sem cumprimento. Um “bom dia” ou “boa tarde” logo na chegada deixa o cliente à vontade desde o início.' WHERE "texto" = 'Saudação inicial' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Você foi cordial com o cliente, se apresentou com simpatia e falou com respeito durante o atendimento.', "mensagem_nao" = 'Faltou se apresentar de forma cordial. Dizer o seu nome e mostrar disposição em ajudar aproxima o cliente.' WHERE "texto" = 'Apresentação cordial' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Você identificou o cliente pelo nome e cadastro — isso deixa o atendimento pessoal e facilita as próximas compras.', "mensagem_nao" = 'O cliente não foi identificado. Perguntar o nome ou consultar o cadastro personaliza o atendimento.' WHERE "texto" = 'Identificação do cliente' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Você conduziu bem o atendimento, com perguntas abertas e objetivas para entender o que o cliente realmente precisava.', "mensagem_nao" = 'A condução pode melhorar: perguntas abertas, como “para que você vai usar?”, ajudam a entender a real necessidade do cliente.' WHERE "texto" = 'Condução do atendimento' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Você se manteve presente e interagiu com o cliente o tempo todo, mostrando interesse de verdade.', "mensagem_nao" = 'Faltou interação durante o atendimento. Manter a conversa e acompanhar o cliente mostra que você está ali por ele.' WHERE "texto" = 'Interação ativa durante o atendimento' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Sua postura e comunicação foram muito boas: clareza, educação e atenção ao cliente do começo ao fim.', "mensagem_nao" = 'Postura e comunicação merecem atenção — o tom de voz, a clareza e a linguagem corporal fazem diferença na experiência do cliente.' WHERE "texto" = 'Postura e comunicação' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Você ofereceu um produto complementar — ótimo para a experiência do cliente e para as vendas da loja.', "mensagem_nao" = 'Não houve oferta complementar. Sugerir um item que combine com a compra agrega valor ao atendimento.' WHERE "texto" = 'Upselling' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'A loja estava organizada e limpa — o cliente encontra um ambiente agradável logo na entrada.', "mensagem_nao" = 'Organização e limpeza precisam de atenção. Um ambiente arrumado muda a percepção do cliente sobre a loja.' WHERE "texto" = 'Organização e limpeza do ambiente' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Vitrine e exposição estavam no padrão, valorizando os produtos.', "mensagem_nao" = 'A vitrine e a exposição estavam fora do padrão. Rever a disposição dos produtos ajuda a atrair e vender mais.' WHERE "texto" = 'Vitrine e exposição de produtos no padrão' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'A comunicação visual das campanhas vigentes estava aplicada corretamente.', "mensagem_nao" = 'Faltou aplicar a comunicação visual das campanhas vigentes — o cliente precisa enxergar as ofertas.' WHERE "texto" = 'Comunicação visual / campanhas vigentes aplicadas' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Estrutura e equipamentos estavam em ordem e funcionando.', "mensagem_nao" = 'Havia problemas de estrutura ou equipamentos. Vale registrar e acompanhar a solução.' WHERE "texto" = 'Estrutura e equipamentos em ordem' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'Os processos operacionais — abertura, caixa e cadastro — estavam sendo seguidos corretamente.', "mensagem_nao" = 'Algum processo operacional (abertura, caixa ou cadastro) não estava sendo seguido. Vale reforçar o passo a passo com a equipe.' WHERE "texto" = 'Processos operacionais seguidos' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
UPDATE "perguntas" SET "mensagem_sim" = 'A equipe mostrou bom clima e postura adequada no atendimento.', "mensagem_nao" = 'O clima e a postura da equipe merecem atenção — isso aparece para o cliente.' WHERE "texto" = 'Clima e postura geral da equipe' AND "mensagem_sim" IS NULL AND "mensagem_nao" IS NULL;
